```

```javascript
// Go binding outline (pseudo)
import "C"
import (
  "fmt"
  "unsafe"
)

func GetMessage() (string, error) {
  var n C.size_t
  if C.get_message(nil, &n) != 0 { return "", fmt.Errorf("error") }
  buf := make([]byte, int(n))
  if C.get_message((*C.char)(unsafe.Pointer(&buf[0])), &n) != 0 { return "", fmt.Errorf("error") }
  return string(buf[:int(n)-1]), nil
}
```

